begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; end $$;
create function pg_temp.denied(q text,expected text) returns void language plpgsql as $$
begin begin execute q; exception when others then
 if position(expected in sqlerrm)>0 then return; end if; raise exception 'Wrong refusal: % (expected %)',sqlerrm,expected;
end; raise exception 'Unexpected permission: %',q; end $$;
create temp table f(k text primary key,v uuid);
